def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent cooperation
    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Streaks of opponent actions at end
    last_opp = history[-1][1]
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == last_opp:
            streak += 1
        else:
            break

    remaining = 100 - n

    # Early cooperation window
    if n < 3:
        return 'C'

    # Detect pure always-defect quickly
    if opp_c == 0:
        return 'D'
    # Detect almost always defect
    if n >= 8 and opp_d >= n - 1:
        return 'D'

    # Detect pure always-cooperate: cooperate early, exploit at end
    if opp_d == 0:
        if remaining <= 5:
            return 'D'
        return 'C'

    # Count opponent defections in recent window
    recent_len = 10 if n >= 10 else n
    recent_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_d += 1

    # Count my defections in recent window
    recent_my_d = 0
    for i in range(n - recent_len, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    # Detect periodic/alternating opponent: alternate D on their D positions
    # If opponent defected ~2 of last 5 rounds, treat as periodic
    if n >= 10:
        win5_d = 0
        for i in range(n - 5, n):
            if history[i][1] == 'D':
                win5_d += 1
        win10_d = 0
        for i in range(n - 10, n):
            if history[i][1] == 'D':
                win10_d += 1
        # Opponent mixes defection at moderate rate - punish when last D, reward C
        if win10_d * 2 >= 3 and win10_d * 2 <= 8:
            # Mixed opponent: retaliate against D, cooperate on C
            if last_opp == 'D':
                # Punish but don't get stuck: alternate
                if streak >= 2:
                    return 'D'
                return 'D' if recent_my_d >= 2 else 'D'
            return 'C'

    # Late game exploitation
    if remaining <= 4:
        if opp_c * 2 > n:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if remaining <= 10:
        if opp_c * 3 > n * 2:
            return 'D'
        if last_opp == 'D' and streak >= 2:
            return 'D'
        if last_opp == 'C':
            return 'C'
        return 'D' if opp_c * 2 < n else 'C'

    # Mid-game: reciprocate with forgiveness
    if last_opp == 'D':
        if streak >= 3:
            # Long defection streak: defect, but with rare forgiveness to escape loops
            if streak >= 6 and rng.random() < 0.2:
                return 'C'
            return 'D'
        if streak == 2:
            # Two in a row: mostly defect
            return 'D' if rng.random() < 0.85 else 'C'
        # Single D: retaliate but forgive
        if recent_my_d >= 2:
            # We've been punishing a lot; try cooperation to restore
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # Opponent cooperated last
    if streak >= 2:
        # Mutually cooperating recently
        # Occasional probe for exploitation against nice opponents
        if n > 15 and opp_d * 8 < n and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent just returned to C after D
    if recent_my_d >= 1 and last_opp == 'C':
        # Forgive after our punishment
        return 'C'

    return 'C'
